 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each nonzero cell is replaced by the zero-mask of the original grid,
    # scaled as a tile and colored with that cell's value.
    zero_mask = [[cell == 0 for cell in row] for row in grid]
    out = [[0 for _ in range(w * w)] for _ in range(h * h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                for dr in range(h):
                    for dc in range(w):
                        if zero_mask[dr][dc]:
                            out[r * h + dr][c * w + dc] = value
    return out
